body.script:
        (function() {
          var iframe = document.getElementById('mainFrame');
          var doc = iframe.contentDocument || iframe.contentWindow.document;
          doc.open();
          doc.write(`






  Nex Game Platform
  <\/script>



🎮 Nex Game Platform<\/h1>

Kies een game of zoek naar een specifieke titel<\/p>
  <\/header>





      ⚠️ Er is een fout opgetreden<\/span>
    <\/div>




      🔄 Reset<\/button>
      🎲 Willekeurig<\/button>
    <\/div>






<\/div>



<\/div>
        <\/div>

Laden...<\/div>
      <\/div>
      <\/nex-game>
    <\/div>



      <\/span>
      Laden...<\/span>
    <\/div>




📚 Alle Games<\/h2>

<\/div>
    <\/div>
  <\/div>


    let currentGid = "main-game";
    let currentAlias = "2048";

    const gameContainer = document.getElementById("gameContainer");
    const loadingOverlay = document.getElementById("loadingOverlay");
    const progressFill = document.getElementById("progressFill");
    const loadingText = document.getElementById("loadingText");
    const statusDot = document.getElementById("statusDot");
    const statusText = document.getElementById("statusText");
    const errorMessage = document.getElementById("errorMessage");
    const errorText = document.getElementById("errorText");
    const galleryGrid = document.getElementById("galleryGrid");
    const searchInput = document.getElementById("searchInput");

    function setStatus(state, message) {
      statusDot.className = "dot";
      if (state === "loading") {
        statusDot.classList.add("loading");
        statusText.textContent = message || "Laden...";
      } else if (state === "ready") {
        statusDot.classList.add("ready");
        statusText.textContent = message || "Klaar om te spelen!";
      } else if (state === "error") {
        statusDot.classList.add("error");
        statusText.textContent = message || "Fout";
      }
    }

    function showError(msg) {
      errorText.textContent = msg || "Onbekende fout";
      errorMessage.classList.add("visible");
      setTimeout(() => errorMessage.classList.remove("visible"), 5000);
    }

    function updateProgress(pct) {
      progressFill.style.width = Math.min(pct, 100) + "%";
      loadingText.textContent = "Laden... " + Math.round(Math.min(pct, 100)) + "%";
    }

    function loadGame(alias) {
      currentAlias = alias;
      errorMessage.classList.remove("visible");
      loadingOverlay.classList.remove("hidden");
      updateProgress(0);
      setStatus("loading", "Laden...");

      const gid = "game-" + Date.now() + "-" + Math.random().toString(36).substr(2, 6);
      currentGid = gid;

      gameContainer.setAttribute("alias", alias);
      gameContainer.setAttribute("gid", gid);

      setTimeout(() => {
        if (window.nex && window.nex[gid]) {
          const game = window.nex[gid];
          game.on("progress", (data) => updateProgress(data.progress || 0));
          game.on("ready", () => {
            updateProgress(100);
            loadingText.textContent = "Klaar! 🎮";
            setStatus("ready", "\"" + alias + "\" is klaar!");
            setTimeout(() => {
              loadingOverlay.classList.add("hidden");
              game.start();
            }, 400);
          });
          game.on("error", (err) => {
            loadingOverlay.classList.add("hidden");
            setStatus("error", "Fout bij laden");
            showError("Kan \"" + alias + "\" niet laden: " + (err.message || "Onbekende fout"));
          });
        } else {
          setTimeout(() => {
            loadingOverlay.classList.add("hidden");
            setStatus("ready", "\"" + alias + "\" geladen");
          }, 2000);
        }
      }, 100);
    }

    function resetGame() {
      loadGame(currentAlias);
    }

    function loadRandomGame() {
      if (window.nex && window.nex.metadata) {
        const aliases = window.nex.metadata.getAllAliases();
        if (aliases.length > 0) {
          const random = aliases[Math.floor(Math.random() * aliases.length)];
          loadGame(random);
          searchInput.value = "";
          filterGames("");
        }
      }
    }

    function filterGames(query) {
      const cards = galleryGrid.querySelectorAll(".gallery-card");
      const q = query.toLowerCase().trim();
      cards.forEach(card => {
        const alias = card.dataset.alias.toLowerCase();
        const name = card.dataset.name.toLowerCase();
        const match = !q || alias.includes(q) || name.includes(q);
        card.style.display = match ? "" : "none";
      });
    }

    function buildGallery() {
      if (!window.nex || !window.nex.metadata) {
        setTimeout(buildGallery, 500);
        return;
      }

      const allGames = window.nex.metadata.getAllMetadata();
      galleryGrid.innerHTML = "";

      Object.values(allGames).forEach(game => {
        const card = document.createElement("div");
        card.className = "gallery-card";
        card.dataset.alias = game.alias;
        card.dataset.name = game.name;
        card.innerHTML = '
          <img src="${game.img}" alt="${game.name}" loading="lazy" onerror="this.src='data:image/svg+xml,🎮'">



${game.name}

${game.category || "Game"}

        ';
        card.onclick = () => {
          loadGame(game.alias);
          searchInput.value = "";
          filterGames("");
        };
        galleryGrid.appendChild(card);
      });
    }

    document.addEventListener("DOMContentLoaded", function() {
      buildGallery();
      setTimeout(() => loadGame("2048"), 300);
    });

    if (window.nex) {
      window.nex.ready = window.nex.ready || function() {};
      const origReady = window.nex.ready;
      window.nex.ready = function() {
        origReady();
        buildGallery();
      };
    }

    console.log("🎮 Nex Game Platform geladen!");
  <\/script>
<\/body>
<\/html>
`);
          doc.close();
        })();
